import{_ as i,C as t,c as r,o as d,aa as c,G as o}from"./chunks/framework.Cn7WEiMX.js";const h=JSON.parse('{"title":"📮 事件","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/MMOInventory/api/events.md","filePath":"wiki/MMOInventory/api/events.md"}'),s={name:"wiki/MMOInventory/api/events.md"};function l(p,e,v,m,u,_){const a=t("NolebaseGitContributors"),n=t("NolebaseGitChangelog");return d(),r("div",null,[e[0]||(e[0]=c('<h1 id="📮-事件" tabindex="-1">📮 事件 <a class="header-anchor" href="#📮-事件" aria-label="Permalink to &quot;📮 事件&quot;">​</a></h1> <p>本章简要讲述了 MMOInventory 可以发起的 Bukkit 事件。</p> <h2 id="inventoryupdateevent" tabindex="-1"><code>InventoryUpdateEvent</code> <a class="header-anchor" href="#inventoryupdateevent" aria-label="Permalink to &quot;`InventoryUpdateEvent`&quot;">​</a></h2> <p>每次界面内容更新后触发。<code>#getPreviousItem</code> 返回替换前的物品，若无则返回 <code>null</code>。<code>#getNewItem</code> 则返回替换后的物品，若无则返回 <code>null</code>。<code>#getInventoryData</code> 返回玩家的界面数据。<code>#getSlot</code> 则返回被点击的格子位置。</p> <p>该事件无法取消。它一般用于向 MMOItems 发送界面更新。</p> <h2 id="itemequipevent" tabindex="-1"><code>ItemEquipEvent</code> <a class="header-anchor" href="#itemequipevent" aria-label="Permalink to &quot;`ItemEquipEvent`&quot;">​</a></h2> <p><code>InventoryUpdateEvent</code> 的对应可取消部分。只在玩家点击箱子界面内的格子时调用。需要注意的是，它也会在玩家与原版界面中的自定义格子交互时触发。</p> <p>注意，点击编辑物品检测并不容易，这可能会导致与 MMOItems 的更新不同步。解决方法如下：</p> <ul><li>监听先前事件，或设置计划任务，在下一刻通过 <code>InventoryData#setItem</code> 编辑。</li> <li>或编辑对应位置的装备物品，设置其物品类型与元数据。需要注意的是 MMOItems 在诸如减少耐久或降级物品的行为中会这么做。因此需要在此之后再次解析 MMOItems 的修饰符。</li></ul> ',18)),o(a),o(n)])}const M=i(s,[["render",l]]);export{h as __pageData,M as default};
